<script setup>
import { computed, onMounted, ref } from 'vue'
import MarkdownRenderer from '../../components/MarkdownRenderer.vue'
import Icon from '../../components/Icon.vue'
const props=defineProps({books:Object,entry:Object,workspace:Object,initialNote:String})
const n=props.workspace, message=ref('')
const members=computed(()=>props.entry.detail.sources.filter(s=>s.source_type==='personal_note'))
const active=computed(()=>n.draft && n.draft.id===props.entry.noteDraftId)
async function open(id){if(n.draft?.id===id){props.books.rememberNote(id);return}await n.open(id,()=>props.books.rememberNote(id))}
function create(){n.newNote(note=>props.books.rememberNote(note.id))}
async function save(){await n.save();if(n.draft && !n.pending && !n.dirty && !n.error){const result=await props.books.attach({source_type:'personal_note',source_id:n.draft.id,source_version:`r${n.draft.revision}-${n.draft.content_hash}`});message.value=result?'笔记已保存并关联到此笔记本。':'正文已保存，笔记本关联未成功，请核对上方提示后重试。'}}
onMounted(async()=>{await n.load();const id=props.initialNote || props.entry.noteDraftId;if(id)await open(id)})
</script>
<template><section class="notebook-notes"><aside><header><h2>学习笔记</h2><button v-if="!entry.detail.archived" class="product-icon-button" aria-label="新建本笔记本笔记" @click="create"><Icon name="plus" :size="18" /></button></header><button v-for="note in members" :key="note.source_id" :class="{active:note.source_id===entry.noteDraftId}" @click="open(note.source_id)"><Icon name="note" :size="16" /><span>{{note.title}}</span></button><p v-if="!members.length">记录你自己的理解，或把回答另存为笔记。</p><button v-if="entry.noteDraftId && !members.some(s=>s.source_id===entry.noteDraftId)" class="product-text-button" @click="open(entry.noteDraftId)">恢复本笔记本草稿</button></aside><div class="notebook-note-editor"><p v-if="n.error || n.storageError" role="alert" class="product-message error">{{n.error || n.storageError}}</p><p v-if="message || n.notice" role="status" class="product-message">{{message || n.notice}}</p><template v-if="active"><div class="notebook-note-toolbar"><span role="status">{{n.status}}</span><button class="product-primary" :disabled="Boolean(entry.detail.archived || n.busy || books.busy || books.pending)" @click="save">{{n.pending?'核对保存结果':'保存笔记'}}</button></div><label class="sr-only" for="notebook-note-title">笔记标题</label><input id="notebook-note-title" v-model="n.draft.title" class="notebook-note-title" maxlength="120" :disabled="entry.detail.archived" aria-label="笔记标题" /><div v-if="n.conflict" class="product-message">服务器版本已变化，本地草稿保留。<button @click="n.readServer()">读取服务器版本</button><button @click="n.saveAsNew();books.rememberNote(n.draft.id)">另存新草稿</button></div><div class="notebook-note-split"><div><label for="notebook-note-content">Markdown 编辑</label><textarea id="notebook-note-content" v-model="n.draft.content_md" :disabled="entry.detail.archived" spellcheck="false" placeholder="写下你的理解，支持 Markdown 与 LaTeX…" @keydown.ctrl.s.prevent="save" /></div><div class="notebook-note-preview"><span>实时预览</span><MarkdownRenderer :source="n.draft.content_md" /></div></div><p class="notebook-composer-hint">Ctrl + S 保存。草稿沿用原笔记保护机制；笔记编辑不会更新BKT。保存后如需问答，请显式更新来源选择。</p></template><div v-else class="product-empty"><Icon name="note" :size="35" /><h2>留下你的思考</h2><p>从左侧打开笔记，或新建一篇。</p><button v-if="!entry.detail.archived" class="product-primary" @click="create">新建笔记</button></div></div></section></template>
